class SmallBuffer:
    inline[N] bytes          # aligned, part of the object
    heap = (ptr, capacity)   # used only while len > N
    len, tag in {inline, heap}

    def append(bytes):
        if tag is inline and len + len(bytes) > N:
            spill()          # the single transition point
        write(bytes)         # one access path for both states
